// ── Live API IOC types ────────────────────────────────────────────────────────
type LiveIOC = {
  id: string;
  value: string;
  type: string;
  threat: string;
  malware: string;
  confidence: number;
  first_seen: string;
  source: "ThreatFox" | "URLhaus" | "MalwareBazaar" | "Feodo Tracker" | "OpenPhish" | "SSL Blacklist" | "C2 Tracker" | "Emerging Threats";
  link?: string;
  tags?: string[];
};

const CORS_PROXIES = [
  (u: string) => `https://corsproxy.io/?${encodeURIComponent(u)}`,
  (u: string) => `https://api.allorigins.win/raw?url=${encodeURIComponent(u)}`,
  (u: string) => `https://corsproxy.org/?${encodeURIComponent(u)}`,
];

async function safeGetText(url: string, timeout = 15000): Promise<string | null> {
  for (const proxy of CORS_PROXIES) {
    try {
      const ctrl = new AbortController();
      const t = setTimeout(() => ctrl.abort(), timeout);
      const res = await fetch(proxy(url), { signal: ctrl.signal });
      clearTimeout(t);
      if (res.ok) return await res.text();
    } catch { /* try next */ }
  }
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), timeout);
    const res = await fetch(url, { signal: ctrl.signal });
    clearTimeout(t);
    if (res.ok) return await res.text();
  } catch { /* ignore */ }
  return null;
}

async function safePost(url: string, body: any, timeout = 15000): Promise<any> {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), timeout);
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: ctrl.signal,
    });
    clearTimeout(t);
    if (!res.ok) return null;
    return await res.json();
  } catch { return null; }
}

async function safeGet(url: string, timeout = 15000): Promise<any> {
  try {
    const ctrl = new AbortController();
    const t = setTimeout(() => ctrl.abort(), timeout);
    const res = await fetch(url, { signal: ctrl.signal });
    clearTimeout(t);
    if (!res.ok) return null;
    return await res.json();
  } catch { return null; }
}

async function fetchThreatFoxIOCs(): Promise<LiveIOC[]> {
  const d = await safePost("https://threatfox-api.abuse.ch/api/v1/", { query: "get_iocs", days: 3 });
  if (!d?.data) return [];
  return (d.data as any[]).slice(0, 100).map(item => ({
    id: String(item.id),
    value: item.ioc,
    type: item.ioc_type,
    threat: item.threat_type_desc || item.threat_type,
    malware: item.malware_printable,
    confidence: item.confidence_level,
    first_seen: item.first_seen,
    source: "ThreatFox" as const,
    link: `https://threatfox.abuse.ch/ioc/${item.id}/`,
    tags: item.tags || [],
  }));
}

async function fetchURLhausIOCs(): Promise<LiveIOC[]> {
  const d = await safeGet("https://urlhaus-api.abuse.ch/v1/urls/recent/limit/100/");
  if (!Array.isArray(d?.urls)) return [];
  return (d.urls as any[]).slice(0, 100).map((item, idx) => ({
    id: `urlhaus-${idx}`,
    value: item.url,
    type: "url",
    threat: item.threat || "malware_download",
    malware: item.tags?.join(", ") || "unknown",
    confidence: 90,
    first_seen: item.date_added,
    source: "URLhaus" as const,
    link: item.urlhaus_link,
    tags: item.tags || [],
  }));
}

async function fetchFeodoTrackerIOCs(): Promise<LiveIOC[]> {
  const d = await safeGet("https://feodotracker.abuse.ch/downloads/ipblocklist.json");
  if (!Array.isArray(d)) return [];
  return (d as any[]).slice(0, 100).map((item, idx) => ({
    id: `feodo-${item.ip_address}-${idx}`,
    value: item.ip_address,
    type: "ip",
    threat: "botnet_c2",
    malware: item.malware || "Botnet C2",
    confidence: item.status === "online" ? 95 : 75,
    first_seen: item.first_seen || new Date().toISOString(),
    source: "Feodo Tracker" as const,
    link: `https://feodotracker.abuse.ch/browse/host/${item.ip_address}/`,
    tags: [item.country, item.malware, item.port ? `Port:${item.port}` : null].filter(Boolean) as string[],
  }));
}

async function fetchOpenPhishIOCs(): Promise<LiveIOC[]> {
  const text = await safeGetText("https://openphish.com/feed.txt");
  if (!text) return [];
  const urls = text.split("\n").map(l => l.trim()).filter(l => l.startsWith("http")).slice(0, 100);
  return urls.map((url, idx) => ({
    id: `openphish-${idx}`,
    value: url,
    type: "url",
    threat: "phishing",
    malware: "Phishing",
    confidence: 85,
    first_seen: new Date().toISOString(),
    source: "OpenPhish" as const,
    link: "https://openphish.com/",
    tags: ["phishing", "credential_harvest"],
  }));
}

async function fetchSSLBlacklistIOCs(): Promise<LiveIOC[]> {
  const d = await safeGet("https://sslbl.abuse.ch/blacklist/sslipblacklist.json");
  if (!Array.isArray(d?.blacklist)) return [];
  return (d.blacklist as any[]).slice(0, 100).map((item, idx) => ({
    id: `sslbl-${item.DstIP}-${idx}`,
    value: `${item.DstIP}:${item.DstPort}`,
    type: "ip",
    threat: "ssl_c2",
    malware: item.Malware || "C2 via SSL",
    confidence: 90,
    first_seen: item.Timestamp || new Date().toISOString(),
    source: "SSL Blacklist" as const,
    link: `https://sslbl.abuse.ch/blacklist/`,
    tags: ["botnet", "ssl_c2", item.Malware].filter(Boolean) as string[],
  }));
}

async function fetchC2TrackerIOCs(): Promise<LiveIOC[]> {
  const text = await safeGetText("https://raw.githubusercontent.com/montysecurity/C2-Tracker/main/data/all.txt");
  if (!text) return [];
  const lines = text.split("\n").map(l => l.trim()).filter(l => l && !l.startsWith("#"));
  return lines.slice(0, 100).map((line, idx) => {
    const parts = line.split(",");
    const ip = parts[0]?.trim();
    const family = parts[1]?.trim() || "C2";
    return {
      id: `c2tracker-${idx}`,
      value: ip,
      type: "ip",
      threat: "c2_infrastructure",
      malware: family,
      confidence: 80,
      first_seen: new Date().toISOString(),
      source: "C2 Tracker" as const,
      link: "https://github.com/montysecurity/C2-Tracker",
      tags: ["c2", family].filter(Boolean),
    };
  }).filter(i => /^\d{1,3}(\.\d{1,3}){3}$/.test(i.value));
}

async function fetchMalwareBazaarIOCs(): Promise<LiveIOC[]> {
  const d = await safePost("https://mb-api.abuse.ch/api/v1/", { query: "get_recent", selector: "100" });
  if (!d?.data) return [];
  return (d.data as any[]).slice(0, 100).map(item => ({
    id: item.sha256_hash,
    value: item.sha256_hash,
    type: "sha256",
    threat: "malware_sample",
    malware: item.signature || item.file_type || "unknown",
    confidence: 95,
    first_seen: item.first_seen,
    source: "MalwareBazaar" as const,
    link: `https://bazaar.abuse.ch/sample/${item.sha256_hash}/`,
    tags: item.tags || [],
  }));
}

type ThreatItem = {
  id: string;
  title: string;
  link: string;
  severity: string;
  iocs: { cves?: string[]; ipv4?: string[]; sha256?: string[]; md5?: string[]; domains?: string[] } | null;
  ai_summary?: string | null;
  ai_summary_model?: string | null;
  ai_summary_generated_at?: string | null;
};

type IOCEntry = { value: string; type: "CVE" | "IP" | "SHA256" | "MD5" | "Domain"; count: number; items: ThreatItem[] };

function CopyBtn({ value }: { value: string }) {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    navigator.clipboard.writeText(value).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
  };
  return (
    <button
      onClick={copy}
      className="shrink-0 rounded p-0.5 text-muted-foreground hover:text-foreground transition-colors"
      title="Copy"
    >
      {copied ? <Check className="h-3 w-3 text-success" /> : <Copy className="h-3 w-3" />}
    </button>
  );
}

