export default function TrendingIOCs() {
  const { toast } = useToast();
  const navigate = useNavigate();
  const [items, setItems] = useState<ThreatItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState<string>("all");
  const [expandedCard, setExpandedCard] = useState<string | null>(null);

  // Live API state
  const [liveIOCs, setLiveIOCs] = useState<LiveIOC[]>([]);
  const [liveLoading, setLiveLoading] = useState(false);
  const [liveSearch, setLiveSearch] = useState("");
  const [liveSrcFilter, setLiveSrcFilter] = useState("all");
  const [liveTypeFilter, setLiveTypeFilter] = useState("all");
  const [liveLastFetched, setLiveLastFetched] = useState<Date | null>(null);

  const fetchLiveAPIs = useCallback(async () => {
    setLiveLoading(true);
    try {
      const [tf, uh, mb, feodo, op, sslbl, c2t] = await Promise.allSettled([
        fetchThreatFoxIOCs(),
        fetchURLhausIOCs(),
        fetchMalwareBazaarIOCs(),
        fetchFeodoTrackerIOCs(),
        fetchOpenPhishIOCs(),
        fetchSSLBlacklistIOCs(),
        fetchC2TrackerIOCs(),
      ]);
      const all: LiveIOC[] = [
        ...(tf.status === "fulfilled" ? tf.value : []),
        ...(uh.status === "fulfilled" ? uh.value : []),
        ...(mb.status === "fulfilled" ? mb.value : []),
        ...(feodo.status === "fulfilled" ? feodo.value : []),
        ...(op.status === "fulfilled" ? op.value : []),
        ...(sslbl.status === "fulfilled" ? sslbl.value : []),
        ...(c2t.status === "fulfilled" ? c2t.value : []),
      ];
      const seen = new Set<string>();
      const deduped = all.filter(ioc => { if (seen.has(ioc.value)) return false; seen.add(ioc.value); return true; });
      setLiveIOCs(deduped.sort((a, b) => b.first_seen.localeCompare(a.first_seen)));
      setLiveLastFetched(new Date());
      const sources = [tf,uh,mb,feodo,op,sslbl,c2t].filter(r => r.status === "fulfilled").length;
      toast({ title: `Live IOCs — ${deduped.length} indicators from ${sources}/7 sources`, description: "ThreatFox · URLhaus · MalwareBazaar · Feodo · OpenPhish · SSL-BL · C2Tracker" });
    } catch (err: any) {
      toast({ title: "Live feed error", description: err.message, variant: "destructive" });
    }
    setLiveLoading(false);
  }, [toast]);

  // Fetch live APIs on mount
  useEffect(() => { fetchLiveAPIs(); }, [fetchLiveAPIs]);

  useEffect(() => {
    (async () => {
      let { data, error } = await supabase
        .from("threat_items")
        .select("id,title,link,severity,iocs,ai_summary,ai_summary_model,ai_summary_generated_at")
        .not("iocs", "is", null)
        .order("created_at", { ascending: false })
        .limit(1000);
      if (error?.message?.includes("ai_summary")) {
        const fallback = await supabase
          .from("threat_items")
          .select("id,title,link,severity,iocs")
          .not("iocs", "is", null)
          .order("created_at", { ascending: false })
          .limit(1000);
        data = fallback.data as any;
        error = fallback.error as any;
      }
      if (error) {
        toast({ title: "Failed to load", description: error.message, variant: "destructive" });
      } else {
        setItems((data || []).filter((i) => i.iocs) as ThreatItem[]);
      }
      setLoading(false);
    })();

    // Real-time: prepend new IOC-rich items as they arrive
    const channel = supabase
      .channel("iocs_live")
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "threat_items" }, (payload) => {
        const item = payload.new as ThreatItem;
        if (item.iocs) setItems(prev => [item, ...prev]);
      })
      .on("postgres_changes", { event: "UPDATE", schema: "public", table: "threat_items" }, (payload) => {
        const updated = payload.new as ThreatItem;
        setItems((prev) => {
          const idx = prev.findIndex((i) => i.id === updated.id);
          if (idx === -1) return prev;
          const next = prev.slice();
          next[idx] = { ...next[idx], ...updated };
          return next;
        });
      })
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [toast]);

  const iocMap = useMemo(() => {
    const map = new Map<string, IOCEntry>();
    for (const item of items) {
      if (!item.iocs) continue;
      const add = (value: string, type: IOCEntry["type"]) => {
        if (!value || value.length < 4) return;
        const key = `${type}:${value}`;
        const existing = map.get(key);
        if (existing) {
          existing.count++;
          if (existing.items.length < 5) existing.items.push(item);
        } else {
          map.set(key, { value, type, count: 1, items: [item] });
        }
      };
      (item.iocs.cves || []).forEach((v) => add(v, "CVE"));
      (item.iocs.ipv4 || []).forEach((v) => add(v, "IP"));
      (item.iocs.sha256 || []).forEach((v) => add(v, "SHA256"));
      (item.iocs.md5 || []).forEach((v) => add(v, "MD5"));
      (item.iocs.domains || []).forEach((v) => add(v, "Domain"));
    }
    return [...map.values()].sort((a, b) => b.count - a.count);
  }, [items]);

  const filtered = useMemo(() => {
    let out = iocMap;
    if (typeFilter !== "all") out = out.filter((i) => i.type === typeFilter);
    if (search.trim()) {
      const q = search.trim().toLowerCase();
      out = out.filter((i) =>
        i.value.toLowerCase().includes(q) ||
        (i.malware || "").toLowerCase().includes(q) ||
        (i.tags || []).some((t: string) => t.toLowerCase().includes(q))
      );
    }
    return out.slice(0, 120);
  }, [iocMap, typeFilter, search]);

  const typeCounts = useMemo(() => {
    const counts: Record<string, number> = { CVE: 0, IP: 0, SHA256: 0, MD5: 0, Domain: 0 };
    for (const i of iocMap) counts[i.type] = (counts[i.type] || 0) + 1;
    return counts;
  }, [iocMap]);

  const types = ["all", "CVE", "IP", "SHA256", "MD5", "Domain"] as const;

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-6">
        <div className="flex items-center gap-3 mb-2">
          <TrendingUp className="h-6 w-6 text-primary" />
          <h1 className="text-3xl font-bold tracking-tight">Trending IOCs</h1>
          <Badge variant="outline" className="border-success/40 text-success text-[10px]">
            <span className="mr-1.5 h-1.5 w-1.5 rounded-full bg-success inline-block animate-pulse" />
            Live
          </Badge>
        </div>
        <p className="text-muted-foreground">
          Most frequently observed indicators of compromise across {items.length.toLocaleString()} ingested threat items.
          Click any IOC to expand external lookups or run multi-source enrichment.
        </p>
      </div>

      {/* Stats row */}
      <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 mb-6">
        {(["CVE", "IP", "SHA256", "MD5", "Domain"] as const).map((t) => (
          <button
            key={t}
            onClick={() => setTypeFilter(typeFilter === t ? "all" : t)}
            className={`rounded-lg border p-3 text-left transition-all ${
              typeFilter === t ? TYPE_COLORS[t] + " ring-1 ring-current" : "border-border/60 bg-card/60 hover:border-primary/40"
            }`}
          >
            <div className="text-xl font-bold tabular-nums">{typeCounts[t] || 0}</div>
            <div className="text-xs text-muted-foreground mt-0.5">{t}s</div>
          </button>
        ))}
      </div>

      <Tabs defaultValue="intel" className="mb-0">
        <TabsList className="mb-4 bg-card/60">
          <TabsTrigger value="intel" className="gap-1.5">
            <TrendingUp className="h-3.5 w-3.5" /> Intel Feed ({iocMap.length})
          </TabsTrigger>
          <TabsTrigger value="live" className="gap-1.5">
            <Radio className="h-3.5 w-3.5 text-green-500" /> Live APIs
            {liveIOCs.length > 0 && <Badge className="ml-1 text-[9px] bg-green-500/20 text-green-400 border-green-500/30 border">{liveIOCs.length}</Badge>}
          </TabsTrigger>
        </TabsList>

        {/* ── Live APIs tab ───────────────────────────────────────────────────── */}
        <TabsContent value="live">
          <div className="flex flex-wrap gap-2 mb-4">
            <LiveSearchInput value={liveSearch} onChange={setLiveSearch} placeholder="Search IOC, malware, tag…" className="flex-1 min-w-48" />
            <div className="flex gap-1 flex-wrap">
              {["all","ThreatFox","URLhaus","MalwareBazaar","Feodo Tracker","OpenPhish","SSL Blacklist","C2 Tracker"].map(s => (
                <Button key={s} size="sm" variant={liveSrcFilter === s ? "default" : "outline"} onClick={() => setLiveSrcFilter(s)} className="text-xs">
                  {s === "all" ? "All Sources" : s}
                </Button>
              ))}
            </div>
            <div className="flex gap-1">
              {["all","url","sha256","ip","domain"].map(t => (
                <Button key={t} size="sm" variant={liveTypeFilter === t ? "default" : "outline"} onClick={() => setLiveTypeFilter(t)} className="text-xs capitalize">
                  {t}
                </Button>
              ))}
            </div>
            <Button size="sm" variant="outline" onClick={fetchLiveAPIs} disabled={liveLoading} className="gap-1.5">
              <RefreshCw className={`h-3.5 w-3.5 ${liveLoading ? "animate-spin" : ""}`} />
              {liveLoading ? "Fetching…" : "Refresh"}
            </Button>
            {liveLastFetched && (
              <span className="text-xs text-muted-foreground self-center">
                Updated {liveLastFetched.toLocaleTimeString()}
              </span>
            )}
          </div>

          {liveLoading && liveIOCs.length === 0 ? (
            <div className="text-center py-16 text-muted-foreground">
              <Radio className="h-8 w-8 mx-auto mb-3 animate-pulse text-green-500" />
              Fetching from ThreatFox · URLhaus · MalwareBazaar · Feodo Tracker · OpenPhish · SSL-BL · C2Tracker…
            </div>
          ) : (
            <>
              <p className="text-xs text-muted-foreground mb-3">
                {liveIOCs.filter(ioc => {
                  if (liveSrcFilter !== "all" && ioc.source !== liveSrcFilter) return false;
                  if (liveTypeFilter !== "all" && ioc.type !== liveTypeFilter) return false;
                  if (liveSearch.trim() && !ioc.value.toLowerCase().includes(liveSearch.toLowerCase()) && !ioc.malware.toLowerCase().includes(liveSearch.toLowerCase())) return false;
                  return true;
                }).length} IOCs · 7 sources: ThreatFox · URLhaus · MalwareBazaar · Feodo Tracker · OpenPhish · SSL-BL · C2Tracker
              </p>
              <div className="flex flex-col gap-1.5">
                {liveIOCs.filter(ioc => {
                  if (liveSrcFilter !== "all" && ioc.source !== liveSrcFilter) return false;
                  if (liveTypeFilter !== "all" && ioc.type !== liveTypeFilter) return false;
                  if (liveSearch.trim() && !ioc.value.toLowerCase().includes(liveSearch.toLowerCase()) && !ioc.malware.toLowerCase().includes(liveSearch.toLowerCase())) return false;
                  return true;
                }).slice(0, 200).map(ioc => (
                  <Card key={ioc.id} className="border-border/60 bg-card/60 hover:border-primary/40 transition-all">
                    <CardContent className="p-3 flex items-start gap-3">
                      <Badge variant="outline" className={`text-[9px] shrink-0 mt-0.5 ${
                        ioc.source === "ThreatFox" ? "border-orange-500/40 text-orange-400" :
                        ioc.source === "URLhaus" ? "border-blue-500/40 text-blue-400" :
                        ioc.source === "MalwareBazaar" ? "border-purple-500/40 text-purple-400" :
                        ioc.source === "Feodo Tracker" ? "border-red-500/40 text-red-400" :
                        ioc.source === "OpenPhish" ? "border-pink-500/40 text-pink-400" :
                        ioc.source === "SSL Blacklist" ? "border-yellow-500/40 text-yellow-400" :
                        ioc.source === "C2 Tracker" ? "border-cyan-500/40 text-cyan-400" :
                        "border-muted-foreground/40 text-muted-foreground"
                      }`}>{ioc.source}</Badge>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="font-mono text-xs truncate max-w-xs">{ioc.value}</span>
                          <button onClick={() => navigator.clipboard.writeText(ioc.value)} className="shrink-0 text-muted-foreground hover:text-foreground">
                            <Copy className="h-3 w-3" />
                          </button>
                          <Badge variant="outline" className="text-[9px]">{ioc.type}</Badge>
                          <span className="text-[9px] text-orange-400 font-medium">{ioc.malware}</span>
                          <span className="ml-auto text-[9px] text-muted-foreground">{new Date(ioc.first_seen).toLocaleDateString()}</span>
                        </div>
                        <div className="mt-1 flex items-center gap-2 flex-wrap">
                          <span className="text-[10px] text-muted-foreground">{ioc.threat}</span>
                          {ioc.confidence && <Badge variant="outline" className="text-[9px]">Conf: {ioc.confidence}%</Badge>}
                          {(ioc.tags || []).slice(0, 4).map(t => <Badge key={t} variant="secondary" className="text-[9px]">{t}</Badge>)}
                          {ioc.link && (
                            <a href={ioc.link} target="_blank" rel="noopener noreferrer" className="ml-auto text-[10px] text-primary hover:underline flex items-center gap-0.5">
                              <Link2 className="h-3 w-3" /> Source
                            </a>
                          )}
                          <button onClick={() => navigate(`/lookup?q=${encodeURIComponent(ioc.value)}`)} className="text-[10px] text-primary hover:underline flex items-center gap-0.5">
                            <ScanSearch className="h-3 w-3" /> Lookup
                          </button>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </>
          )}
        </TabsContent>

        {/* ── Intel Feed tab ───────────────────────────────────────────────────── */}
        <TabsContent value="intel">

      {/* Search + filter bar */}
      <div className="flex flex-wrap gap-3 mb-6">
        <LiveSearchInput value={search} onChange={setSearch} placeholder="Search IOCs…" className="flex-1 min-w-48" />

        <div className="flex gap-1.5 flex-wrap">
          {types.map((t) => (
            <Button
              key={t}
              size="sm"
              variant={typeFilter === t ? "default" : "outline"}
              onClick={() => setTypeFilter(t)}
              className="text-xs"
            >
              <Filter className="h-3 w-3 mr-1" />
              {t === "all" ? "All" : t}
            </Button>
          ))}
        </div>
      </div>

      {loading ? (
        <div className="text-center py-16 text-muted-foreground">Aggregating IOCs…</div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16 text-muted-foreground">No IOCs match your filter. Feeds may still be loading.</div>
      ) : (
        <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">
          {filtered.map((ioc) => {
            const key = `${ioc.type}:${ioc.value}`;
            const isExpanded = expandedCard === key;
            const links = LOOKUP_LINKS[ioc.type]?.(ioc.value) || [];
            return (
              <Card
                key={key}
                className={`border-border/60 bg-card/60 backdrop-blur cursor-pointer transition-all ${
                  isExpanded ? "ring-1 ring-primary/50" : "hover:border-primary/30"
                }`}
                onClick={() => setExpandedCard(isExpanded ? null : key)}
              >
                <CardHeader className="pb-2">
                  <div className="flex items-center justify-between gap-2">
                    <Badge variant="outline" className={`text-[10px] ${TYPE_COLORS[ioc.type]}`}>
                      {ioc.type}
                    </Badge>
                    <span className="text-xs text-muted-foreground ml-auto">
                      {ioc.count} mention{ioc.count > 1 ? "s" : ""}
                    </span>
                    <CopyBtn value={ioc.value} />
                  </div>
                  <CardTitle className="text-sm font-mono break-all leading-relaxed">{ioc.value}</CardTitle>
                </CardHeader>
                <CardContent className="pt-0">
                  {/* Source articles */}
                  <div className="flex flex-col gap-1 mb-2">
                    {ioc.items.slice(0, isExpanded ? 5 : 2).map((item) => (
                      <a
                        key={item.id}
                        href={item.link}
                        target="_blank"
                        rel="noopener noreferrer"
                        onClick={(e) => e.stopPropagation()}
                        className="text-xs text-muted-foreground hover:text-primary flex items-center gap-1 truncate group"
                      >
                        <span
                          className={`inline-block h-1.5 w-1.5 shrink-0 rounded-full ${
                            SEV_COLORS[item.severity]?.split(" ")[0] || "bg-muted"
                          }`}
                        />
                        <ExternalLink className="h-3 w-3 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity" />
                        <span className="truncate">{item.title}</span>
                      </a>
                    ))}
                  </div>

                  {/* Lookup links (visible when expanded) */}
                  {isExpanded && (
                    <div className="border-t border-border/40 pt-2 mt-2 space-y-2">
                      <button
                        onClick={(e) => { e.stopPropagation(); navigate(`/lookup?value=${encodeURIComponent(ioc.value)}`); }}
                        className="w-full inline-flex items-center justify-center gap-1.5 rounded px-3 py-1.5 text-[11px] font-semibold bg-primary text-primary-foreground hover:bg-primary/90 transition-colors"
                      >
                        <ScanSearch className="h-3 w-3" /> Multi-Source Enrich
                      </button>
                      {links.length > 0 && (
                        <>
                          <p className="text-[10px] text-muted-foreground uppercase tracking-wide">External Lookups</p>
                          <div className="flex flex-wrap gap-1.5">
                            {links.map((l) => (
                              <a
                                key={l.label}
                                href={l.url}
                                target="_blank"
                                rel="noopener noreferrer"
                                onClick={(e) => e.stopPropagation()}
                                className="inline-flex items-center gap-1 rounded px-2 py-0.5 text-[11px] font-medium bg-primary/10 text-primary hover:bg-primary/20 transition-colors border border-primary/20"
                              >
                                {l.label}
                                <ExternalLink className="h-2.5 w-2.5" />
                              </a>
                            ))}
                          </div>
                        </>
                      )}
                    </div>
                  )}

                  {!isExpanded && links.length > 0 && (
                    <p className="text-[10px] text-muted-foreground mt-1">Click to expand {links.length} lookup links</p>
                  )}
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
        </TabsContent>
      </Tabs>
    </div>
  );
}
